def perform(self):
    (ret, num_handles) = self.curl.perform()
    if ret != pycurl.E_CALL_MULTI_PERFORM and num_handles == 0:
        self.running = False
    (num, completed, failed) = self.curl.info_read()
    [self.close_request(com) for com in completed]
    for fail in failed:
        self.handle_failed_request(fail)
    if not self.running:
        return False
    return True

    def handle_failed_request(self, fail):
        print(f'Request failed: {fail}')

def perform(self):
    (ret, num_handles) = self.curl.perform()
    if ret != pycurl.E_CALL_MULTI_PERFORM and num_handles == 0:
        self.running = False
    (num, completed, failed) = self.curl.info_read()
    [self.close_request(com) for com in completed]
    for handle in failed:
        self.handle_failed_request(handle)
    if not self.running:
        return False
    return True

def handle_failed_request(self, handle):
    print(f'Request failed: {handle}')

def _query(self, query):
    old = query.copy()
    self.pre_translation(query)
    if old != query:
        log.debug('RHBugzilla altered query to: %s', query)
    ret = self._proxy.Bug.search(query)
    if self._is_older_rhbz():
        for bug in ret['bugs']:
            self.post_translation(query, bug)
    return ret

def _is_older_rhbz(self):
