def get_table_resize(table_data, table_col_count, column_widths, page_width) -> bool:
    resize = False
    try:
        resize = table_data['fitToPageWidth']
    except:
        total_table_width = sum(column_widths)
        if total_table_width > page_width:
            resize = True
    return resize

def get_table_resize(table_data, table_col_count) -> bool:
    resize = False
    page_width = 800
    column_width = 100
    total_table_width = table_col_count * column_width
    try:
        resize = table_data['fitToPageWidth']
    except:
        if total_table_width > page_width:
            resize = True
    return resize

