def get_working_copy_status_json(repo):
    if repo.is_bare:
        return None
    table_wc = repo.working_copy.tabular
    result = []
    if table_wc:
        for part in table_wc.parts:
            part_status = {'path': part.clean_location, 'changes': get_diff_status_json(part)}
            result.append(part_status)
    return result

def get_working_copy_status_json(repo):
    if repo.is_bare:
        return None
    working_copies = repo.working_copy.parts
    result = []
    for wc in working_copies:
        table_wc_path = wc.tabular.clean_location if wc.tabular else None
        result.append({'path': table_wc_path, 'changes': get_diff_status_json(repo)})
    return result

