def run_ingest_job_and_kick_scheduler_on_completion(self, args: IngestArgsType):
    self._run_ingest_job(args)
    while not self.is_ingest_job_complete():
        time.sleep(0.1)
    self.kick_scheduler()
    logging.info('Done running task. Returning from run_ingest_job_and_kick_scheduler_on_completion')

