def PyTuple_Size(space, ref):
    if not PyTuple_Check(ref):
        raise ValueError('Provided reference is not a valid tuple object.')
    ref_tup = rffi.cast(PyTupleObject, ref)
    return ref_tup.c_size

def PyTuple_Size(space, ref):
