    ref_tup = rffi.cast(PyTupleObject, ref)
    return ref_tup.c_size

import re
def _obfuscate_command(self,
                       command_args: Sequence[CommandArg],
                       obfuscate_args: Optional[Iterable[CommandArg]] = None) -> ObfuscatedCommand:
    obfuscate_args = set(chain((obfuscate_args or []), self.default_obfuscation))
    obfuscated = ' '.join(
        self.obfuscation if any(re.match(arg, str(command_arg)) for arg in obfuscate_args) else shlex.quote(str(command_arg))
        for command_arg in command_args)
    )
    return ObfuscatedCommand(obfuscated)

import re

def _obfuscate_command(self, command_args: Sequence[CommandArg], obfuscate_args: Optional[Iterable[CommandArg]]=None) -> ObfuscatedCommand:
    obfuscate_args = set(chain(obfuscate_args or [], self.default_obfuscation))
    obfuscated = ' '.join((self.obfuscation if any((re.fullmatch(str(arg), str(pattern)) for pattern in obfuscate_args)) else shlex.quote(str(arg)) for arg in command_args))
    return ObfuscatedCommand(obfuscated)

