def process_msg(self, msg):
    cmd_id = rlp.decode(msg[:1], sedes=sedes.big_endian_int)
    self.logger.debug('Processing msg with cmd_id: {}'.format(cmd_id))
    proto = self.get_protocol_for(cmd_id)
    if proto is None:
        self.logger.warn('No protocol found for cmd_id {}'.format(cmd_id))
        return
    decoded_msg = proto.process(cmd_id, msg)
    if cmd_id == Hello.id:
        hello_capabilities = decoded_msg.get('capabilities', [])
        self.sub_protocols = self.populate_sub_protocols(self.capabilities, hello_capabilities)
        self.logger.debug('Got hello: {}'.format(decoded_msg))

def populate_sub_protocols(self, capabilities, hello_capabilities):
    sub_protocols = []
    for capability in hello_capabilities:
        if capability in capabilities:
            sub_protocols.append(capability)
    return sub_protocols

