def keyPressEvent(self, event):
    if self.preprocess_keyevent(event):
        return
    if self.busy and (not self.input_mode):
        self.eventqueue.append(keyevent2tuple(event))
        event.accept()
    else:
        self.postprocess_keyevent(event)

