def predicate(self, predicate, object, depth=1):
    writer = self.writer
    store = self.store
    writer.push(predicate)
    if isinstance(object, Literal):
        attributes = ''
        if object.language:
            writer.attribute(XMLLANG, object.language)
        if object.datatype:
            writer.attribute(RDF.datatype, object.datatype)
        writer.text(object)
    elif object in self.__serialized or not (object, None, None) in store:
        if isinstance(object, BNode):
            if more_than(store.triples((None, None, object)), 0):
                writer.attribute(RDF.nodeID, fix(object))
        else:
            writer.attribute(RDF.resource, self.relativize(object))
    elif first(store.objects(object, RDF.first)):
        collection = object
        self.__serialized[object] = 1
        print('Warning: Any assertions on object other than RDF.first and RDF.rest are ignored, including RDF.List.')
        writer.attribute(RDF.parseType, 'Collection')
        col = Collection(store, object)
        for item in col:
            if isinstance(item, URIRef):
                self.forceRDFAbout.add(item)
            self.subject(item)
            if not isinstance(item, URIRef):
                self.__serialized[item] = 1
    elif first(store.triples_choices((object, RDF.type, [OWL_NS.Class, RDFS.Class]))) and isinstance(object, URIRef):
        writer.attribute(RDF.resource, self.relativize(object))
    elif depth <= self.max_depth:
        self.subject(object, depth + 1)
    elif isinstance(object, BNode):
        if not object in self.__serialized and (object, None, None) in store and (len(list(store.subjects(object=object))) == 1):
            self.subject(object, depth + 1)
        else:
            writer.attribute(RDF.nodeID, fix(object))
    else:
        writer.attribute(RDF.resource, self.relativize(object))
    writer.pop(predicate)

