        elif self.identity_type == IdentityType.SYSTEM:
            self.system = obj.get('system')
            if not self.system:
                raise ValueError('The identity.system field is mandatory for system-type identities')
            elif not self.system.get('cert_type'):
                raise ValueError('The cert_type field is mandatory for system-type identities')
            elif self.system.get('cert_type') not in CertType.__members__.values():
                raise ValueError('The cert_type is invalid. Please check the valid cert_type values.')
            elif not self.system.get('cn'):
                raise ValueError('The cn field is mandatory for system-type identities')
        threadctx.account_number = obj['account_number']
    else:
        raise ValueError('Neither the account_number or token has been set')

def _parse_expression(self, inTemplate: bool) -> ASTExpression:
    if inTemplate:
        return self._parse_assignment_expression(inTemplate=inTemplate)
    else:
        first_expression = self._parse_assignment_expression(inTemplate=inTemplate)
        self._expect(',')
        second_expression = self._parse_assignment_expression(inTemplate=inTemplate)
        return ASTExpression(first_expression, second_expression)

async def modify_webhook(self, webhook_id: str, new_data: dict) -> _utils.DiscordObject:
    webhook_url = f'https://discord.com/api/webhooks/{webhook_id}'
    async with aiohttp.ClientSession() as session:
        async with session.patch(webhook_url, json=new_data) as response:
            if response.status == 200:
                return await response.json()
            else:
                raise Exception(f'Failed to modify webhook: {response.status}')

def query_by_short_id(context, model, short_id, project_safe=True):
    q = model_query(context, model)
    q = q.filter(model.id.like('%s%%' % short_id))
    if project_safe:
        q = q.filter_by(project=context.project)
    if q.count() == 1:
        return q.first()
    elif q.count() == 0:
        return None
    else:
        raise exception.MultipleChoices(arg=short_id)

