    return self.pilimage

def _processMessage(self, msg):
    res = None
    wspaces = msg.count(' ')
    qmarks = msg.count('?')
    tokens = msg.split()
    if wspaces > 1 and qmarks > 0 or wspaces > 2 or qmarks > 1:
        res = 'ERROR: Cannot parse this command\n'
    elif qmarks:
        if tokens[0] == '*IDN?':
            res = IDN + '\n'
        elif tokens[0] == 'PWR?':
            pin = int(tokens[1])
            if pin < 0 or pin > 7:
                res = 'ERROR: Out of range pin number\n'
            else:
                ans = self._i2crcv >> pin & MASK
                res = str(ans) + '\n'
        elif tokens[0] == 'WMEM?':
            address = int(tokens[1])
            if address < 0 or address >= MEMORY_SIZE:
                res = 'ERROR: Out of range memory address\n'
            else:
                res = str(self.memory[address]) + '\n'
        elif tokens[0] == 'RMEM?':
            address = int(tokens[1])
            if address < 0 or address >= MEMORY_SIZE:
                res = 'ERROR: Out of range memory address\n'
            else:
                res = str(self.memory[address]) + '\n'
        else:
            res = 'ERROR: Cannot parse this command\n'
    elif wspaces:
        pin = int(tokens[1])
        val = int(tokens[2])
        if tokens[0] == 'PWR':
            if pin < 0 or pin > 7:
                res = 'ERROR: Out of range pin number\n'
            else:
                self._i2crcv = self._i2crcv & ~(1 << pin) | val << pin & 1 << pin
                res = '\n'
        elif tokens[0] == 'WMEM':
            address = int(tokens[1])
            value = int(tokens[2])
            if address < 0 or address >= MEMORY_SIZE:
                res = 'ERROR: Out of range memory address\n'
            else:
                self.memory[address] = value
                res = '\n'
        elif tokens[0] == 'RMEM':
            address = int(tokens[1])
            if address < 0 or address >= MEMORY_SIZE:
                res = 'ERROR: Out of range memory address\n'
            else:
                res = str(self.memory[address]) + '\n'
        else:
            res = 'ERROR: Cannot parse this command\n'
    else:
        res = 'ERROR: Cannot parse this command\n'
    if res is not None:
        self._output_buf += res

