    pulp_ctx: PulpContext = ctx.find_object(PulpContext)
    if ctx.parent and ctx.parent.params['repo_type'] == 'file':
        ctx.obj = PulpFileRepositoryVersionContext(pulp_ctx)
    elif ctx.parent and ctx.parent.params['repo_type'] == 'repository':
        ctx.obj = PulpRepositoryVersionContext(pulp_ctx)
    else:
        raise NotImplementedError()

def version(ctx: click.Context) -> None:
    pulp_ctx: PulpContext = ctx.find_object(PulpContext)
    if ctx.parent:
        repo_type = ctx.parent.params.get('repo_type')
        if repo_type == 'file':
            ctx.obj = PulpFileRepositoryVersionContext(pulp_ctx)
        elif repo_type == 'repository':
            ctx.obj = PulpRepositoryVersionContext(pulp_ctx)
        else:
            raise NotImplementedError(f'Unsupported repo_type: {repo_type}')
    else:
        raise NotImplementedError('No parent context found.')

