def create_from_list(self, data, constructor, error):
    result = []
    names = [x for x in map(str.strip, re.split('[, ]+', data)) if x]
    for name in names:
        result.append(constructor(name))
    return set(result)

def create_from_list(self, data, constructor, error):
    result = []
    names = [x for x in map(str.strip, re.split('[, ]+', data)) if x]
    for name in names:
        try:
            result.append(constructor(name))
        except Exception as e:
            error.append(str(e))
    return set(result)

