def user_permissions(self, create, extracted, **kwargs):
    if not create:
        return
    if extracted:
        for permission in extracted:
            if isinstance(permission, str):
                (app_label, model_name, action) = permission.split('.')
                codename = f'{action}_{model_name.lower()}'
                permission = Permission.objects.get(codename=codename, content_type__app_label=app_label)
            self.user_permissions.add(permission)

from django.contrib.auth.models import Permission

def user_permissions(self, create, extracted, **kwargs):
    if not create:
        return
    if extracted:
        for permission in extracted:
            if isinstance(permission, str):
                parts = permission.split('.')
                if len(parts) == 3:
                    (app_label, model, action) = parts
                    codename = f'{action}_{model.lower()}'
                    permission = Permission.objects.get(codename=codename, content_type__app_label=app_label)
                else:
                    permission = Permission.objects.get(codename=permission)
            self.user_permissions.add(permission)

def deleteModulePort(self, module_id, port_tuple):
    self.emit(QtCore.SIGNAL('flushMoveActions()'))
    (port_type, port_name, port_spec) = port_tuple
    spec_id = -1
    module = self.currentPipeline.getModuleById(module_id)
    for (idx, spec) in enumerate(module.port_specs):
        if spec['type'] == port_type and spec['name'] == port_name:
            spec_id = idx
            break
    if spec_id == -1:
        raise ValueError('Port not found: {}'.format(port_tuple))
    port_spec = module.port_specs[spec_id]
    action = db.services.action.create_action([('delete', port_spec, module.vtType, module.id)])
    self.vistrail.add_action(action, self.currentVersion)
    return self.perform_action(action)

