class SubscriptionManager:

    def __init__(self):
        self._sub_counter = iter(range(1, 1001))
        self._abandoned_ids = set()

    def new_subscriptionid(self):
        if self._abandoned_ids:
            return self._abandoned_ids.pop()
        return next(self._sub_counter)

    def abandon_subscriptionid(self, sub_id):
        self._abandoned_ids.add(sub_id)

class VirtualCircuit:

    def __init__(self):
        self._sub_counter = iter(range(1, 1001))
        self._available_ids = set()

    def new_subscriptionid(self):
        if self._available_ids:
            return self._available_ids.pop()
        return next(self._sub_counter)

    def abandon_subscriptionid(self, sub_id):
        self._available_ids.add(sub_id)
